 public bool Reserve(Style04EnemySupportMotion.Token token,Style04EnemySupportMotion.Snapshot s,HexAppliedOncePlan plan,int generation){if(_cancelled||_plan!=null||_outcome>=0||generation<0||!s.Active||s.EndRequestedAt>=0||!token.Equals(_token)||!Owns(s)||plan.ExecutionIndex!=token.ExecutionIndex||plan.EnemyId!=s.ProfileId||plan.MoveId!=s.MoveId||(_profile=="enemy_sludge_berserker"&&(plan.Status!="wound"||plan.Blocked||plan.Amount<1||plan.Amount>3||plan.Outcome is not GameEvent_StatusInflicted{Status:"wound"} vomitActual||vomitActual.Amount!=plan.Amount))||(_profile=="enemy_elite_mirror_djinn"&&(plan.Status!="weak"||(plan.Blocked?(plan.Amount!=0||plan.Outcome is not GameEvent_PlayerArtifactBlocked{Status:"weak"}):(plan.Amount!=3||plan.Outcome is not GameEvent_StatusInflicted{Status:"weak",Amount:3}))))||(_profile=="enemy_elite_slaver"&&(plan.Status!="vulnerable"||(plan.Blocked?(plan.Amount!=0||plan.Outcome is not GameEvent_PlayerArtifactBlocked{Status:"vulnerable"}):(plan.Amount!=3||plan.Outcome is not GameEvent_StatusInflicted{Status:"vulnerable",Amount:3}))))||(_profile=="enemy_gaping_maw"&&(plan.Status!="vulnerable"||(plan.Blocked?(plan.Amount!=0||plan.Outcome is not GameEvent_PlayerArtifactBlocked{Status:"vulnerable"}):(plan.Amount!=2||plan.Outcome is not GameEvent_StatusInflicted{Status:"vulnerable",Amount:2}))))||(_profile=="enemy_maw_hunter"&&(plan.Status!="slow"||(plan.Blocked?(plan.Amount!=0||plan.Outcome is not GameEvent_PlayerArtifactBlocked{Status:"slow"}):(plan.Amount!=2||plan.Outcome is not GameEvent_StatusInflicted{Status:"slow",Amount:2}))))||(_profile=="enemy_chomper"&&(plan.Status!="junk"||plan.Blocked||plan.Amount<1||plan.Amount>2||plan.Outcome is not GameEvent_StatusInflicted{Status:"junk"} junkActual||junkActual.Amount!=plan.Amount))||(_profile=="enemy_chimera_3"&&(plan.Status!="scald"||plan.Blocked||plan.Amount<1||plan.Amount>3||plan.Outcome is not GameEvent_StatusInflicted{Status:"scald"} growlActual||growlActual.Amount!=plan.Amount))||((_profile is "enemy_cinder_imp" or "enemy_scald_gnat")&&(plan.Status!="scald"||plan.Blocked||plan.Amount<1||plan.Amount>2||plan.Outcome is not GameEvent_StatusInflicted{Status:"scald"} actual||actual.Amount!=plan.Amount)))return false;_plan=plan;_generation=generation;return true;}
