 private BruteAuthoredFrames.Snapshot Pick(string clip,float age,string reason,int owner,Style04EnemyMotion.Snapshot a){var d=_clips[clip];float t=Math.Max(0,age);int i=0;while(i<d.Length-1&&t>=d[i]){t-=d[i];i++;}return State=new(clip,clip,i,reason,false,true,owner,a.Version,a.ExecutionIndex,a.AcceptedContacts,a.LastOrdinal,a.LastContactAt);}
 public BruteAuthoredFrames.Snapshot Sample(float now,Style04EnemyMotion.Snapshot a,Style04EnemySupportMotion.Snapshot s,int owner,bool dead,BruteAuthoredFrames.Snapshot fallback){
  if(!float.IsFinite(now)||now<0||dead||_cancelled||a.Active||!s.Active||s.OwnerVersion!=owner||!Owns(s)||fallback.Reason=="hurt-notification")return State=fallback;
